def compute(vars):
    cabinets_sales = vars["v1"]
    doors_sales = vars["v2"]
    ratio = None if doors_sales == 0 else cabinets_sales / doors_sales
    return {
        "value": ratio,
        "trace": {
            "cabinets_sales": cabinets_sales,
            "doors_sales": doors_sales,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
